def is_not_prime(n):
    """
    Returns True if n is NOT a prime number, False if n IS a prime number.
    """
    if n < 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return True
    return False

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0
    doubled = s + s
    for i in range(1, n + 1):
        if doubled[i:i + n] == s:
            return i
    return n

def remove_Occ(s, ch):
    s = list(s)
    first_index = None
    last_index = None
    for i, c in enumerate(s):
        if c == ch:
            if first_index is None:
                first_index = i
            last_index = i
    if first_index is None:
        return ''.join(s)
    if first_index == last_index:
        del s[first_index]
    else:
        del s[last_index]
        del s[first_index]
    return ''.join(s)

import re

def text_lowercase_underscore(text):
    """
    Find sequences of lowercase letters joined with an underscore.
    Returns the match object's matched string if found, otherwise None.
    """
    pattern = r'^[a-z]+_[a-z]+$'
    result = re.match(pattern, text)
    if result:
        return result.group()
    else:
        return None

def is_woodall(number):
    """
    Check if a number is a Woodall number.
    A Woodall number has the form: n * 2^n - 1 for some positive integer n.
    """
    if number < 1:
        return False

    n = 1
    while True:
        value = n * (2 ** n) - 1
        if value == number:
            return True
        if value > number:
            return False
        n += 1

def is_octagonal(n):
    """
    Returns the nth octagonal number.

    Octagonal numbers follow the formula: n * (3n - 2)
    """
    return n * (3 * n - 2)

def smallest_num(nums):
    if not nums:
        return None
    return min(nums)

def recursive_list_sum(data):
    """
    Recursively sum elements in a list.
    Handles nested lists by summing their elements as well.
    """
    total = 0
    for item in data:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total
